glsl:
#version 300 es

precision highp float;
precision highp int;

struct VertexOutput {
    vec4 position;
    vec2 uv;
};
layout(location = 0) in vec2 _p2vs_location0;
smooth out vec2 _vs2fs_location0;

void main() {
    vec2 a_position = _p2vs_location0;
    VertexOutput out_ = VertexOutput(vec4(0.0), vec2(0.0));
    vec2 uv = ((a_position + vec2(1.0)) * 0.5);
    out_.uv = vec2(uv.x, (1.0 - uv.y));
    out_.position = vec4(a_position, 0.0, 1.0);
    VertexOutput _e17 = out_;
    gl_Position = _e17.position;
    _vs2fs_location0 = _e17.uv;
    gl_Position.yz = vec2(-gl_Position.y, gl_Position.z * 2.0 - gl_Position.w);
    return;
}

wgsl:
// Adapted from Liquid Glass Studio, Charles Yin, MIT. See NOTICE.md.
// Fullscreen quad vertex shader for WebGPU
// Similar to vertex.glsl but with v_uv.y flipped so that v_uv=(0,0) is top-left,
// matching WebGPU's texture/framebuffer coordinate convention.

struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
};

@vertex
fn vs_main(@location(0) a_position: vec2f) -> VertexOutput {
  var out: VertexOutput;
  let uv = (a_position + 1.0) * 0.5;
  // Flip Y: in WebGPU, texture v=0 is top, but clip y=+1 is top.
  // So top of screen has uv.y=0, bottom has uv.y=1.
  out.uv = vec2f(uv.x, 1.0 - uv.y);
  out.position = vec4f(a_position, 0.0, 1.0);
  return out;
}
